import io.grpc.Metadata;
import io.grpc.ServerCall;
import io.grpc.Status;

final class QuoteServer {
    record Quote(long watermark) {}
    static void respond(ServerCall<String,String> call, long minimumWatermark, Quote snapshot) {
        call.sendHeaders(new Metadata());
        if (snapshot.watermark() < minimumWatermark) {
            call.close(Status.UNAVAILABLE.withDescription("below minimum watermark"), new Metadata());
            return;
        }
        call.sendMessage(Long.toString(snapshot.watermark()));
        call.close(Status.OK, new Metadata());
    }
}

